    controls = {};
}
let control = controls[msg.topic];
if (typeof control !== 'object') {
    controls[msg.topic] = {};
}
let content = controls[msg.topic][msg.id];
if (typeof content !== 'object') {
    controls[msg.topic][msg.id] = {};
}

controls[msg.topic][msg.id] = msg.payload;

global.set('controls', controls, 'memoryOnly');

msg.payload = controls;

return msg;

let units = global.get('units', 'default');
if (typeof units === 'object') {
    for (const host in units) {
        return {
            'topic': host,
            'payload': host
        }
    }
}

return;

let describe = global.get('describe', 'memoryOnly');

let entries = msg.payload.split(',');
for (const i in entries) {
    let pair = entries[i].split('=');
    let id = pair[0];
    let label = id;
    let raw = pair[1];
    let val = raw.split('/');

    // get readbale label
	if (typeof describe.label[label] == 'string') {
        label = describe.label[label];
	}

    if (id === 'curr_day_heat' ||
        id === 'prev_1day_heat' ||
        id === 'curr_day_cool' ||
        id === 'prev_1day_cool'
    ) {
        // Convert numeric value to number
        for (const k in val) {
            val[k] = Number(val[k]);
        }

        node.send({
            'topic': msg.topic,
            'id': id,
            'payload': {
                'label': label,
                'raw': raw,
                'val': val
            }
        });
    }
}

return;

flow.set('current_unit', '', 'memoryOnly');

