if (msg.payload === '1' || msg.payload === '7') {
    msg.payload = '0';
}

return msg;

let current_unit = flow.get('current_unit', 'memoryOnly');
let control = global.get('controls["' + current_unit + '"]', 'memoryOnly');
let unit = global.get('units["' + current_unit + '"]', 'default');

if (typeof control === 'object' && typeof unit === 'object') {
    control[msg.topic]['raw'] = msg.payload.toString();

    let res = {
        'topic': current_unit,
        'url': 
            'http://' + unit.host + '/aircon/set_control_info?' +
            'pow=' + control['pow']['raw'] + '&' +
            'mode=' + control['mode']['raw'] + '&' +
