if (size < 2) {
    msg.class = '';
    msg.enabled = true;
    msg.payload = {
        'model': 'BRP069Bxx',
        'name': 'Clim_' + size,
        'location': 'Maison',
        'host': '192.168.0.101'
    }
} else {
    msg.class = 'remove';
    msg.enabled = false;
    msg.payload = {};
}

return msg;

let units = global.get('units', 'default') || {};
if (typeof units[msg.payload.host] === 'object') {
    msg.payload = 'Cet élément est déjà configuré'
    node.send([null, msg]);
} else if (msg.payload.name !== ' ' && msg.payload.location !== ' ' && msg.payload.host !== ' ' && msg.payload.port !== ' ') {
    units[msg.payload.host] = msg.payload;
    global.set('units', units, 'default');
    node.send([msg, null]);
}

return;

let res = msg.payload;
let exists = false;

if (Array.isArray(res)) {
    msg.payload = [];
    msg.class = '';
    msg.enabled = true;

    for (const k in res) {
        if (res[k] > 0) {
            exists = true;
        }
        msg.payload[k] = {
            'key': k,
            'val': res[k]
        };
    }
}

if (exists === false) {
    msg.class = 'remove';
    msg.enabled = false;
    msg.payload = [];
}

return msg;
